#include <Arduino.h>
TaskHandle_t timerWorker = nullptr;
TimerHandle_t sampleTimer = nullptr;
void timerCallback(TimerHandle_t) { if (timerWorker) xTaskNotifyGive(timerWorker); }
void timerWorkerTask(void*) { for (;;) { ulTaskNotifyTake(pdTRUE, portMAX_DELAY); Serial.println("timer event"); } }
void setup() { Serial.begin(115200); if (xTaskCreate(timerWorkerTask, "timer-worker", 2048, nullptr, 1, &timerWorker) != pdPASS) { Serial.println("timer worker creation failed"); return; } sampleTimer = xTimerCreate("sample", pdMS_TO_TICKS(1000), pdTRUE, nullptr, timerCallback); if (sampleTimer == nullptr) { Serial.println("timer creation failed"); return; } if (xTimerStart(sampleTimer, 0) != pdPASS) { Serial.println("timer start failed"); xTimerDelete(sampleTimer, 0); sampleTimer = nullptr; } }
void loop() { vTaskDelay(pdMS_TO_TICKS(1000)); }

#include <Arduino.h>
TaskHandle_t timerWorker = nullptr;
TimerHandle_t timerHandle = nullptr;
void onTimer(TimerHandle_t) { if (timerWorker) xTaskNotifyGive(timerWorker); }
void timerWorkerTask(void*) { for (;;) { ulTaskNotifyTake(pdTRUE, portMAX_DELAY); Serial.println("timer event"); } }
void setup() { Serial.begin(115200); if (xTaskCreate(timerWorkerTask, "timer-worker", 2048, nullptr, 1, &timerWorker) != pdPASS) return; timerHandle = xTimerCreate("sample", pdMS_TO_TICKS(1000), pdTRUE, nullptr, onTimer); if (timerHandle == nullptr || xTimerStart(timerHandle, 0) != pdPASS) Serial.println("timer setup failed"); }
void loop() { vTaskDelay(pdMS_TO_TICKS(1000)); }
